const D = { density:.6, energy:.6, wind:.35, speed:1, hue:210, scale:1, y:.9, x:.5, style:'streak', seed:0, act:'steady' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const frc=v=>v-Math.floor(v);
const md=(a,n)=>((a%n)+n)%n;
const lrp=(a,b,t)=>a+(b-a)*t;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};

const W=width,Hh=height,u=Math.min(W,Hh);
const H=md(P.hue,360);
const st=P.style;
const isSumi=st==='sumi', isNeon=st==='neon', isMatrix=st==='matrix';
const act=P.act||'steady';

let envD=1, envW=1;
if(act==='drizzle'){ envD=0.45; envW=0.7; }
else if(act==='storm'){ envD=1.3; envW=1.6; }
const arc=0.55+0.6*K.intensity;
const dens=clp(P.density*envD,0,1.4);
const en=clp(P.energy*arc,0,1.3);
const gust=(P.wind + 0.32*Math.sin(K.t*0.23) + 0.12*Math.sin(K.t*0.71))*envW + A.bass*0.45;
const grY=P.y*Hh;

if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

if(isMatrix){
  // ---- digital rain columns (abstracted dot-matrix) ----
  noStroke();
  const cols=Math.round(lrp(14,64,dens));
  const cellH=u*0.03*P.scale;
  const tail=Math.round(lrp(6,17,dens));
  for(let c=0;c<cols;c++){
    const cx=(c+0.5)/cols*W;
    const spd=(0.5+fr(c*3+1)*0.9)*P.speed;
    const span=Hh/cellH+tail+4;
    const head=frc(fr(c*3+2)+K.t*spd*0.45)*span-tail-2;
    for(let k=0;k<tail;k++){
      const idx=Math.floor(head)-k;
      const y=idx*cellH;
      if(y<-cellH||y>Hh+cellH) continue;
      const f=k/tail;
      const jitter=fr(c*17+idx)>0.5?0.22:0;
      if(k===0){ fill(md(H,360),12,100,100); }
      else { fill(md(H+lrp(-4,12,f),360), clp(70-f*24,10,90), lrp(88,16,f), lrp(96,8,f)); }
      const wsz=cellH*0.5*(1+jitter);
      rect(cx-wsz/2, y, wsz, cellH*0.72, 1);
    }
  }
} else {
  // ---- falling drops with wind tilt + depth parallax ----
  const nD=Math.round(lrp(30,220,dens));
  for(let i=0;i<nD;i++){
    const depth=fr(i*3+2);
    const fallSp=lrp(0.35,0.9,depth)*P.speed;
    const life=frc(fr(i*3+1)+K.t*fallSp*0.5);
    const baseX=fr(i*3+3)*1.2-0.1;
    const x=baseX*W + gust*life*u*0.6;
    const y=-0.08*Hh + life*(grY+0.16*Hh);
    const len=u*0.04*P.scale*(0.4+en)*lrp(0.45,1.5,depth);
    const slopeX=gust*len*1.1;
    const sw=lrp(0.6,2.4,depth)*P.scale;
    if(isNeon){
      blendMode(ADD);
      stroke(md(H+lrp(-6,12,depth),360),55,100,lrp(10,34,depth)); strokeWeight(sw*2.4);
      line(x,y,x-slopeX,y-len);
      stroke(md(H+lrp(-6,12,depth),360),22,100,lrp(38,88,depth)); strokeWeight(Math.max(0.5,sw*0.7));
      line(x,y,x-slopeX,y-len);
      blendMode(BLEND);
    } else if(isSumi){
      for(let o=0;o<3;o++){ const ox=(o-1)*sw*0.9;
        stroke(md(H,360),lrp(4,15,depth),lrp(58,90,depth),lrp(6,20,depth));
        strokeWeight(Math.max(0.6,sw*(2.2-o*0.5)));
        line(x+ox,y,x-slopeX+ox,y-len); }
    } else {
      stroke(md(H+lrp(-8,10,depth),360),lrp(8,26,depth),lrp(52,90,depth),lrp(22,82,depth)*(0.5+en*0.6));
      strokeWeight(sw);
      line(x,y,x-slopeX,y-len);
    }
  }
  // ---- ground splash rings (continuous, seeded) ----
  if(P.energy>0.02){
    const nS=Math.round(lrp(6,40,dens));
    if(S.spSeed!==P.seed||S.spN!==nS){ S.spSeed=P.seed; S.spN=nS; S.sp=[];
      for(let i=0;i<nS;i++) S.sp.push({x:fr(i+100),ph:fr(i+200),sp:0.6+fr(i+300)*0.8}); }
    noFill();
    for(let i=0;i<nS;i++){ const s2=S.sp[i];
      const life2=frc(s2.ph+K.t*(0.7+s2.sp)*P.speed*0.6);
      const r=life2*u*0.05*P.scale*(0.5+en);
      const a=(1-life2)*(1-life2)*46*en;
      stroke(md(H+6,360),isNeon?45:16,isNeon?100:88,a);
      strokeWeight(Math.max(0.6,u*0.0018));
      ellipse(s2.x*W, grY-u*0.005, r*2, r*0.7); }
  }
  // ---- puddle sheen band (K.t shimmer) ----
  noStroke();
  for(let b2=0;b2<4;b2++){ const yy=grY+(b2/4)*(Hh-grY)*0.9;
    const sh=0.5+0.5*Math.sin(K.t*1.3+b2*1.7+A.bass*3);
    fill(md(H+4,360),22,lrp(28,54,b2/3)*(0.66+0.34*sh),16);
    ellipse(W*0.5, yy, W*1.12, (Hh-grY)*0.5); }
}

blendMode(BLEND); drawingContext.shadowBlur=0;
